mapper.select:

WHERE S.CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
  AND S.ACTIVITY = '1'

  AND S.TRAIN_DIFF_CODE = #{trainDiffCode, jdbcType=VARCHAR}


  AND S.TRAIN_TYPE_CODE = #{trainTypeCode, jdbcType=VARCHAR}

ORDER BY S.CREATE_DATE DESC

SELECT MAX(TRAIN_TYPE_NO)
  FROM EDU_SYSTEM_MANAGER
 WHERE CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
   AND TRAIN_DIFF_CODE = #{trainDiffCode, jdbcType=VARCHAR}

SELECT COUNT(1)
  FROM EDU_SYSTEM_MANAGER
 WHERE CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
   AND ACTIVITY = '1'
   AND TRAIN_DIFF_CODE = #{trainDiffCode, jdbcType=VARCHAR}
   AND TRAIN_TYPE_CODE = #{trainTypeCode, jdbcType=VARCHAR}

mapper.update:
UPDATE EDU_SYSTEM_MANAGER
   SET REMARK = #{remark, jdbcType=VARCHAR},
       UPDATE_DATE = SYSDATE,
       UPDATED_BY = #{adminID, jdbcType=VARCHAR},
       UPDATED_IP = #{adminIP, jdbcType=VARCHAR}
 WHERE SYSMANA_NO = #{sysmanaNo, jdbcType=VARCHAR}
   AND CPNY_ID = #{cpnyId, jdbcType=VARCHAR}

UPDATE EDU_SYSTEM_MANAGER
   SET ACTIVITY = '0',
       UPDATE_DATE = SYSDATE,
       UPDATED_BY = #{adminID, jdbcType=VARCHAR},
       UPDATED_IP = #{adminIP, jdbcType=VARCHAR}
 WHERE SYSMANA_NO = #{sysmanaNo, jdbcType=VARCHAR}
   AND CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
